//! Codex CLI profile — `$CODEX_HOME/llamastash.config.toml`
//! (`~/.codex/llamastash.config.toml` by default).
//!
//! Codex loads `<name>.config.toml` from its home as a layer over
//! `config.toml` when started with `--profile <name>`
//! (`codex-rs/config/src/loader/mod.rs`, `main` `60947e234`, release
//! 0.159.2; also in 0.150.1). So the whole file is ours and the user's
//! `config.toml` is never touched: `codex --profile llamastash` uses
//! llamastash, plain `codex` does not.
//!
//! Codex speaks only the Responses API (`WireApi` has one variant,
//! `responses`). llama-server serves `POST /v1/responses` and maps
//! `reasoning.effort` to `reasoning_effort`, and the proxy forwards it.
//!
//! The key comes from `llamastash api-key` through the provider's `auth`
//! command, so no secret lands on disk.
//!
//! **Effort.** The profile only overrides `config.toml`, so without its
//! own `model_reasoning_effort` the one in `config.toml` (set for OpenAI
//! models) is sent to the local model; checked with codex 0.150.1, a
//! `config.toml` `"minimal"` went out as `reasoning.effort: "minimal"`,
//! which Qwen3.8's template rejects. So a model with effort levels gets
//! the template's default written here. The file is rewritten on each
//! run, but a level the user set in it is kept when the model accepts it.

use std::path::PathBuf;

use crate::init::external::effort::EffortLevels;
use crate::init::external::{Format, PatchContext, ToolPatcher};

pub struct Codex;

/// The profile name, and so the file stem and the `--profile` value.
pub const PROFILE: &str = "llamastash";

/// A TOML basic string.
fn toml_str(s: &str) -> String {
  let mut out = String::with_capacity(s.len() + 2);
  out.push('"');
  for c in s.chars() {
    match c {
      '"' => out.push_str("\\\""),
      '\\' => out.push_str("\\\\"),
      c if c.is_control() => out.push_str(&format!("\\u{:04X}", c as u32)),
      c => out.push(c),
    }
  }
  out.push('"');
  out
}

/// The `model_reasoning_effort` value set at the top level of an existing
/// profile, if any.
fn current_effort(current: &str) -> Option<String> {
  current
    .lines()
    .map(str::trim)
    .take_while(|l| !l.starts_with('['))
    .find_map(|l| {
      let value = l.strip_prefix("model_reasoning_effort")?.trim_start();
      toml_string_value(value.strip_prefix('=')?.trim_start())
    })
}

/// A basic (`"x"`) or literal (`'x'`) TOML string filling the rest of a
/// line, with an optional trailing comment. Escapes are not decoded; no
/// level name has one.
fn toml_string_value(v: &str) -> Option<String> {
  let quote = v.chars().next().filter(|c| *c == '"' || *c == '\'')?;
  let body = &v[1..];
  let end = body.find(quote)?;
  let tail = body[end + 1..].trim_start();
  (tail.is_empty() || tail.starts_with('#')).then(|| body[..end].to_string())
}

/// The level to write: the user's, when the model accepts it, else the
/// template's default, else its highest level.
fn effort_to_write(effort: &EffortLevels, current: Option<&str>) -> Option<String> {
  let accepted = |l: &str| effort.accepts(l) || (effort.can_disable && l == "none");
  current
    .and_then(current_effort)
    .filter(|l| accepted(l))
    .or_else(|| effort.preferred().map(str::to_string))
}

impl ToolPatcher for Codex {
  fn id(&self) -> &'static str {
    "codex"
  }
  fn display_name(&self) -> &'static str {
    "Codex CLI"
  }
  fn default_path(&self) -> Option<PathBuf> {
    let home = std::env::var_os("CODEX_HOME")
      .filter(|v| !v.is_empty())
      .map(PathBuf::from)
      .or_else(|| crate::util::paths::home_dir().map(|h| h.join(".codex")))?;
    Some(home.join(format!("{PROFILE}.config.toml")))
  }
  fn format(&self) -> Format {
    Format::Raw
  }
  fn build_additions(&self, _ctx: &PatchContext) -> serde_json::Value {
    serde_json::Value::Null
  }
  fn raw_body(&self, ctx: &PatchContext) -> Option<String> {
    self.raw_body_from(ctx, None)
  }
  fn raw_body_from(&self, ctx: &PatchContext, current: Option<&str>) -> Option<String> {
    let mut body = format!(
      "# Generated by `llamastash init`. Re-runs rewrite this file and keep\n\
       # only model_reasoning_effort, when the model accepts the level.\n\
       # Use with: codex --profile {PROFILE}\n\n"
    );
    if let Some(m) = ctx.primary().filter(|m| !m.is_embed) {
      body.push_str(&format!(
        "model = {}\nmodel_context_window = {}\n",
        toml_str(&m.id),
        m.declared_context()
      ));
      if let Some(effort) = &m.effort {
        let mut levels = effort.levels.join(", ");
        if effort.can_disable {
          levels.push_str(", none (thinking off)");
        }
        if let Some(level) = effort_to_write(effort, current) {
          body.push_str(&format!(
            "# Levels this model accepts: {levels}. Per run:\n\
             # codex --profile {PROFILE} -c model_reasoning_effort=<level>\n\
             model_reasoning_effort = {}\n",
            toml_str(&level)
          ));
        }
      }
    }
    body.push_str(&format!(
      "model_provider = {}\n\n\
       [model_providers.{PROFILE}]\n\
       name = \"LlamaStash\"\n\
       base_url = {}\n\
       wire_api = \"responses\"\n\n\
       [model_providers.{PROFILE}.auth]\n\
       command = \"llamastash\"\n\
       args = [\"api-key\"]\n",
      toml_str(PROFILE),
      toml_str(&ctx.proxy_base_url),
    ));
    Some(body)
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use crate::init::external::apply;
  use crate::init::external::effort::EffortLevels;

  #[test]
  fn writes_a_profile_for_the_primary_chat_model() {
    let mut ctx = PatchContext::fixture(&["nomic-embed-text-v1.5", "Qwen3.8-27B-UD-Q6_K"]);
    ctx.models[1].context_window = Some(262_144);
    let body = Codex.raw_body(&ctx).expect("body");
    assert!(body.contains("model = \"Qwen3.8-27B-UD-Q6_K\"\n"));
    assert!(body.contains("model_context_window = 262144\n"));
    assert!(body.contains("model_provider = \"llamastash\"\n"));
    assert!(body.contains("base_url = \"http://127.0.0.1:11435/v1\"\n"));
    assert!(body.contains("wire_api = \"responses\"\n"));
    assert!(body.contains("command = \"llamastash\"\nargs = [\"api-key\"]\n"));
    assert!(
      !body.contains("model_reasoning_effort ="),
      "no levels, nothing to pin"
    );
  }

  fn qwen38() -> PatchContext {
    let mut ctx = PatchContext::fixture(&["Qwen3.8-27B-UD-Q6_K"]);
    ctx.models[0].effort = Some(EffortLevels {
      levels: vec!["low".into(), "medium".into(), "xhigh".into()],
      aliases: vec!["high".into()],
      default: Some("xhigh".into()),
      can_disable: true,
    });
    ctx
  }

  #[test]
  fn the_templates_default_effort_is_pinned_so_config_toml_cannot_leak_in() {
    let body = Codex.raw_body(&qwen38()).expect("body");
    assert!(body.contains("# Levels this model accepts: low, medium, xhigh, none (thinking off)."));
    assert!(body.contains("\nmodel_reasoning_effort = \"xhigh\"\n"));
    // Top-level key: it must come before the first table.
    assert!(body.find("model_reasoning_effort").unwrap() < body.find("[model_providers").unwrap());
  }

  #[test]
  fn a_level_the_user_set_survives_a_rewrite_when_the_model_accepts_it() {
    let ctx = qwen38();
    let user = "model = \"x\"\nmodel_reasoning_effort = \"low\"\n[model_providers.llamastash]\n";
    assert!(Codex
      .raw_body_from(&ctx, Some(user))
      .unwrap()
      .contains("model_reasoning_effort = \"low\"\n"));
    let off = "model_reasoning_effort = \"none\"\n";
    assert!(Codex
      .raw_body_from(&ctx, Some(off))
      .unwrap()
      .contains("model_reasoning_effort = \"none\"\n"));
    for kept in [
      "model_reasoning_effort = \"medium\"  # set by hand\n",
      "model_reasoning_effort = 'medium'\n",
    ] {
      assert!(Codex
        .raw_body_from(&ctx, Some(kept))
        .unwrap()
        .contains("model_reasoning_effort = \"medium\"\n"));
    }
    // An alias the template rewrites is accepted too.
    let alias = "model_reasoning_effort = \"high\"\n";
    assert!(Codex
      .raw_body_from(&ctx, Some(alias))
      .unwrap()
      .contains("model_reasoning_effort = \"high\"\n"));
    // A level the template rejects falls back to the default.
    let rejected = "model_reasoning_effort = \"minimal\"\n";
    assert!(Codex
      .raw_body_from(&ctx, Some(rejected))
      .unwrap()
      .contains("model_reasoning_effort = \"xhigh\"\n"));
  }

  #[test]
  fn a_user_level_is_kept_through_apply() {
    let dir = crate::util::test_temp::unique_temp_dir("codex-keep-effort");
    let path = dir.join("llamastash.config.toml");
    let ctx = qwen38();
    apply(&Codex, &ctx, Some(path.clone())).expect("first");
    let edited = std::fs::read_to_string(&path).unwrap().replace(
      "model_reasoning_effort = \"xhigh\"",
      "model_reasoning_effort = \"medium\"",
    );
    std::fs::write(&path, edited).unwrap();
    let second = apply(&Codex, &ctx, Some(path.clone())).expect("second");
    assert!(second.diff_json.is_empty(), "nothing else changed");
    assert!(std::fs::read_to_string(&path)
      .unwrap()
      .contains("model_reasoning_effort = \"medium\""));
    std::fs::remove_dir_all(&dir).ok();
  }

  #[test]
  fn no_chat_model_still_writes_the_provider() {
    let body = Codex
      .raw_body(&PatchContext::fixture(&["nomic-embed-text-v1.5"]))
      .expect("body");
    assert!(!body.contains("\nmodel = "));
    assert!(body.contains("[model_providers.llamastash]"));
  }

  #[test]
  fn ids_are_escaped_as_toml_strings() {
    assert_eq!(toml_str("owner/repo@coder"), "\"owner/repo@coder\"");
    assert_eq!(toml_str("a\"b\\c"), "\"a\\\"b\\\\c\"");
  }

  #[test]
  fn apply_is_idempotent() {
    let dir = crate::util::test_temp::unique_temp_dir("codex-profile");
    let path = dir.join("llamastash.config.toml");
    let ctx = PatchContext::fixture(&["qwen3-coder-30b"]);
    apply(&Codex, &ctx, Some(path.clone())).expect("first");
    let second = apply(&Codex, &ctx, Some(path.clone())).expect("second");
    assert!(second.diff_json.is_empty());
    std::fs::remove_dir_all(&dir).ok();
  }
}
